import{_ as i,o as t,c as o,a2 as a}from"./chunks/framework.LX5S0jbT.js";const u=JSON.parse('{"title":"安全地运行 Pi","description":"","frontmatter":{},"headers":[],"relativePath":"zh/security.md","filePath":"zh/security.md"}'),d={name:"zh/security.md"};function l(r,e,p,c,s,n){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="安全地运行-pi" tabindex="-1">安全地运行 Pi <a class="header-anchor" href="#安全地运行-pi" aria-label="Permalink to &quot;安全地运行 Pi&quot;">​</a></h1><p>将模型生成的命令和代码视为不受信任的内容。Pi 能够以启动它的账户的权限读取、修改和执行文件，并且不会在每次工具调用前请求批准。扩展（extension）、包安装器、语言服务器和其他子进程都以相同的权限运行，除非有操作系统或虚拟化边界加以限制。</p><p>文件、注释、指令、命令输出和模型响应都可能通过提示词注入（prompt injection）左右模型的行为。项目信任（project trust）控制哪些项目资源在启动时加载，但它并不能使这些内容或由此产生的操作变得安全。</p><p>安全来自于限制 Pi 在某个生成的操作出错或带有恶意时能够访问和影响的文件、凭据、进程和网络服务。监视对话记录、使用项目信任、审查更改，这些都不构成安全边界。</p><h2 id="选择运行-pi-的方式" tabindex="-1">选择运行 Pi 的方式 <a class="header-anchor" href="#选择运行-pi-的方式" aria-label="Permalink to &quot;选择运行 Pi 的方式&quot;">​</a></h2><p>不同的运行方式对生成命令可访问的内容施加不同的限制：</p><table tabindex="0"><thead><tr><th>Pi 的运行方式</th><th>仍受保护的内容</th></tr></thead><tbody><tr><td>直接运行，拥有其操作系统用户的权限</td><td>该用户无法访问的一切。专用的用户账户可以收窄这些权限，但 Pi 仍与其他用户共享操作系统和网络。</td></tr><tr><td>完全在容器、虚拟机或沙箱内运行</td><td>你未暴露给该环境的宿主文件和进程。如果你把凭据和网络服务放进环境内部，它们仍可被访问。这通常是最强的实用选项。</td></tr><tr><td>在隔离环境之外运行，只有其内置工具在隔离环境内执行</td><td>通过这些工具执行的操作无法触及宿主资源。Pi 本身和其他扩展仍在边界之外，因此这是一种较弱的隔离形式。</td></tr></tbody></table><p>工作目录控制资源发现和工具的默认位置，但它不能阻止命令访问 Pi 进程可用的其他路径。</p><p>无论选择哪种方式，只提供任务所需的文件和服务。尽量把凭据放在环境之外，或使用范围狭窄、短期的凭据。命令不需要网络时，限制网络访问。</p><p>隔离方法的设置说明和局限，请参见<a href="./containerization.html">在隔离环境中运行 Pi</a>。</p><p><a id="project-trust"></a></p><p><a id="understand-project-trust"></a></p><h2 id="理解项目信任" tabindex="-1">理解项目信任 <a class="header-anchor" href="#理解项目信任" aria-label="Permalink to &quot;理解项目信任&quot;">​</a></h2><p>项目信任控制 Pi 是否加载由工作目录提供的大多数设置和资源。它可以防止一个目录在你批准之前静默加载可执行的扩展。</p><p>项目信任不是一个完整的启动边界。Pi 在选择或创建会话时会读取项目的 <code>sessionDir</code> 设置，而这发生在解析项目信任之前。拒绝信任可以阻止其余项目设置和受保护资源加载，但无法撤销那次初始的会话目录查找。</p><p>项目信任不限制工具调用可以访问或影响的内容。Pi 启动之后，已启用的工具仍然使用 Pi 进程的操作系统权限。目录中的指令和其他内容也会影响模型。</p><h3 id="受项目信任保护的资源" tabindex="-1">受项目信任保护的资源 <a class="header-anchor" href="#受项目信任保护的资源" aria-label="Permalink to &quot;受项目信任保护的资源&quot;">​</a></h3><p>当 Pi 从当前工作目录发现以下任一资源时，会要求做出项目信任决定：</p><ul><li><code>.pi/settings.json</code></li><li><code>.pi/mcp.json</code></li><li><code>.pi/extensions</code>、<code>.pi/skills</code>、<code>.pi/prompts</code> 或 <code>.pi/themes</code></li><li><code>.pi/SYSTEM.md</code> 或 <code>.pi/APPEND_SYSTEM.md</code></li><li>当前目录或祖先目录中的项目 <code>.agents/skills</code></li></ul><p>仅存在一个空的 <code>.pi</code> 目录不需要项目信任。</p><p>授予项目信任后，Pi 可以加载：</p><ul><li>项目设置</li><li>来自 <code>.pi/mcp.json</code> 的项目 MCP 服务器</li><li><code>.pi</code> 下的扩展、技能、提示词模板、主题和系统提示词文件</li><li>通过项目设置配置的缺失包</li><li>项目本地扩展和项目包扩展</li></ul><p>拒绝项目信任会跳过这些受保护的资源，但上述初始的 <code>sessionDir</code> 查找除外。</p><p><code>AGENTS.override.md</code>、<code>AGENTS.md</code> 和 <code>CLAUDE.md</code> 等上下文文件无论项目信任与否都会加载，除非你禁用上下文加载。即使你拒绝了项目信任，也应将目录中的指令视为不受信任的输入。</p><h3 id="pi-如何做出信任决定" tabindex="-1">Pi 如何做出信任决定 <a class="header-anchor" href="#pi-如何做出信任决定" aria-label="Permalink to &quot;Pi 如何做出信任决定&quot;">​</a></h3><p>命令行的 <code>--approve</code> 或 <code>--no-approve</code> 覆盖项优先。当存在受保护资源且没有命令行覆盖项时：</p><ol><li>用户级和命令行扩展可以处理 <code>project_trust</code> 事件。第一个返回 yes 或 no 的扩展拥有该决定权。</li><li>如果没有扩展做出决定，Pi 会查找针对当前目录或其某个父目录已保存的决定。应用最近的决定。</li><li>如果没有适用的已保存决定，Pi 遵循全局的 <code>defaultProjectTrust</code> 设置，其默认值为 <code>&quot;ask&quot;</code>。</li></ol><p>已保存的决定使用规范化的目录路径，存放在：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.pi/agent/trust.json</span></span></code></pre></div><p>使用 <code>/trust</code> 为将来的 Pi 进程保存一个决定。</p><h3 id="没有交互式提示时的项目信任" tabindex="-1">没有交互式提示时的项目信任 <a class="header-anchor" href="#没有交互式提示时的项目信任" aria-label="Permalink to &quot;没有交互式提示时的项目信任&quot;">​</a></h3><p>打印（print）、JSON 和 RPC 模式无法显示内置的信任提示。如果没有命令行覆盖项、扩展或已保存的决定适用：</p><ul><li><code>defaultProjectTrust: &quot;always&quot;</code> 加载受保护的项目资源。</li><li><code>defaultProjectTrust: &quot;ask&quot;</code> 或 <code>&quot;never&quot;</code> 跳过它们。</li></ul><p>自动化运行需要明确的一次性决定时，使用 <code>--approve</code> 或 <code>--no-approve</code>。</p><h2 id="降低影响并改善恢复" tabindex="-1">降低影响并改善恢复 <a class="header-anchor" href="#降低影响并改善恢复" aria-label="Permalink to &quot;降低影响并改善恢复&quot;">​</a></h2><p>以下做法不能替代隔离，但可以减少暴露面或让恢复更容易：</p><ul><li>只授予 Pi 完成任务所需的文件和服务访问权。</li><li>在重大更改之前使用快照、备份或版本控制。</li><li>在加载扩展和包之前先审查它们。扩展在 Pi 进程内部执行。</li><li>优先使用范围狭窄、短期的凭据。</li><li>在把结果应用到另一个系统之前，审查 diff 和生成的输出。</li><li>在导出或分享会话之前先审查它们。会话中可能包含对话期间暴露的提示词、工具参数、命令输出、文件内容和凭据。</li></ul><h2 id="报告安全问题" tabindex="-1">报告安全问题 <a class="header-anchor" href="#报告安全问题" aria-label="Permalink to &quot;报告安全问题&quot;">​</a></h2><p>请遵循仓库的<a href="https://github.com/earendil-works/pi/blob/main/SECURITY.md" target="_blank" rel="noreferrer">安全策略</a>。安全敏感的报告不要开公开 issue。</p><p>本地 agent 的预期行为、来自不受信任内容的提示词注入、缺少内置沙箱，以及用户安装的扩展或技能引发的行为，通常不在安全边界之内——除非报告演示了权限边界绕过，或获得了本地用户原本不具备的访问权。</p>',40)])])}const P=i(d,[["render",l]]);export{u as __pageData,P as default};
